<script setup>
import { onMounted, reactive, ref, watch } from 'vue'
import { tempsTravailService } from '@/services/tempsTravailService'
import http from '@/services/http'
const employes=ref([]),regimes=ref([]),plannings=ref([]),creneaux=ref([]),message=ref(''),erreur=ref(''),edition=ref(null)
const planning=reactive({employeId:'',regimeId:'',dateDebut:'',dateFin:'',motif:''});const creneau=reactive({planningId:'',dateDebut:'',dateFin:'',typeCreneau:'TRAVAIL',libelle:''})
onMounted(async()=>{try{employes.value=(await http.get('/manager/onboarding/employes')).data||[];regimes.value=await tempsTravailService.regimes()}catch(e){erreur.value=e.response?.data?.message||'Chargement impossible.'}})
watch(()=>planning.employeId,async id=>{plannings.value=id?await tempsTravailService.plannings(id):[];creneaux.value=[];creneau.planningId=''})
watch(()=>creneau.planningId,async id=>{creneaux.value=id?await tempsTravailService.creneauxPlanning(id):[]})
async function enregistrerPlanning(){try{await http.post('/temps-travail/plannings',{...planning,employeId:Number(planning.employeId),regimeId:Number(planning.regimeId),dateFin:planning.dateFin||null});plannings.value=await tempsTravailService.plannings(planning.employeId);message.value='Planning enregistré.'}catch(e){erreur.value=e.response?.data?.message||e.message||'Planning refusé.'}}
async function enregistrerCreneau(){try{const data={...creneau,planningId:Number(creneau.planningId)};if(edition.value)await tempsTravailService.modifierCreneau(edition.value.id,data);else await tempsTravailService.creerCreneau(data);creneaux.value=await tempsTravailService.creneauxPlanning(creneau.planningId);edition.value=null;message.value='Créneau enregistré.'}catch(e){erreur.value=e.response?.data?.message||'Créneau refusé.'}}
function modifier(c){edition.value=c;Object.assign(creneau,{planningId:c.planningId,dateDebut:c.dateDebut?.slice(0,16),dateFin:c.dateFin?.slice(0,16),typeCreneau:c.typeCreneau,libelle:c.libelle})}
async function supprimer(c){if(!confirm('Supprimer ce créneau ?'))return;await tempsTravailService.supprimerCreneau(c.id);creneaux.value=creneaux.value.filter(x=>x.id!==c.id)}
async function statut(c,s){const x=await tempsTravailService.changerStatutCreneau(c.id,s);creneaux.value=creneaux.value.map(v=>v.id===c.id?x:v)}
</script>
<template><div class="container-fluid py-4"><h1 class="h3">Planning de l’équipe</h1><div v-if="message" class="alert alert-success">{{message}}</div><div v-if="erreur" class="alert alert-danger">{{erreur}}</div><section class="card card-body mb-3"><h2 class="h5">1. Affecter un planning</h2><form class="row g-2" @submit.prevent="enregistrerPlanning"><div class="col-md-3"><select v-model="planning.employeId" class="form-select" required><option value="">Salarié</option><option v-for="e in employes" :key="e.id" :value="e.id">{{e.prenom}} {{e.nom}}</option></select></div><div class="col-md-3"><select v-model="planning.regimeId" class="form-select" required><option value="">Régime</option><option v-for="r in regimes" :key="r.id" :value="r.id">{{r.libelle}}</option></select></div><div class="col-md-2"><input v-model="planning.dateDebut" type="date" class="form-control" required></div><div class="col-md-2"><input v-model="planning.dateFin" type="date" class="form-control"></div><div class="col-md-2"><button class="btn btn-primary w-100">Attribuer</button></div></form></section><section v-if="plannings.length" class="card card-body mb-3"><h2 class="h5">2. Choisir le planning</h2><div class="row g-2"><div v-for="p in plannings" :key="p.id" class="col-md-4"><button class="btn w-100 text-start" :class="String(creneau.planningId)===String(p.id)?'btn-primary':'btn-outline-primary'" @click="creneau.planningId=p.id">Du {{p.dateDebut}}<span v-if="p.dateFin"> au {{p.dateFin}}</span></button></div></div></section><section v-if="creneau.planningId" class="card card-body"><h2 class="h5">3. Agenda et créneaux</h2><form class="row g-2 align-items-end" @submit.prevent="enregistrerCreneau"><div class="col-md-3"><label class="form-label">Début</label><input v-model="creneau.dateDebut" type="datetime-local" class="form-control" required></div><div class="col-md-3"><label class="form-label">Fin</label><input v-model="creneau.dateFin" type="datetime-local" class="form-control" required></div><div class="col-md-2"><label class="form-label">Type</label><select v-model="creneau.typeCreneau" class="form-select"><option value="TRAVAIL">Travail</option><option value="FORMATION">Formation</option><option value="PAUSE">Pause</option></select></div><div class="col-md-2"><label class="form-label">Libellé</label><input v-model="creneau.libelle" class="form-control"></div><div class="col-md-2"><button class="btn btn-primary w-100">{{edition?'Modifier':'Ajouter'}}</button></div></form><div class="mt-3"><article v-for="c in creneaux" :key="c.id" class="border-start border-4 border-primary p-3 mb-2 d-flex justify-content-between"><div><strong>{{c.libelle||'Travail'}}</strong><div class="small">{{c.dateDebut}} → {{c.dateFin}}</div></div><div class="d-flex gap-1"><select class="form-select form-select-sm" :value="c.statut" @change="statut(c,$event.target.value)"><option value="PLANIFIE">Planifié</option><option value="REALISE">Réalisé</option><option value="ABSENT">Absent</option><option value="ANNULE">Annulé</option></select><button class="btn btn-sm btn-outline-primary" @click="modifier(c)">Modifier</button><button class="btn btn-sm btn-outline-danger" @click="supprimer(c)">Supprimer</button></div></article></div></section></div></template>
